public void trackDrink(Holder<Potion> potion, ServerPlayer player) {
		//reset advancement window if potion changed. Otherwise, continue incrementing the doses
		if (this.lastUsedPotion == null || !Objects.equals(this.lastUsedPotion, potion)) {
			this.dosesDrank = 1;
			this.lastTimeStarted = player.level().getGameTime();
		} else {
			this.dosesDrank++;
		}
		this.lastUsedPotion = potion;

		if (player.isAlive()) {
			TFAdvancements.DRINK_FROM_FLASK.get().trigger(player, this.dosesDrank, Mth.floor((float) (player.level().getGameTime() - this.lastTimeStarted) / 20L), this.lastUsedPotion);
		}
	}

@Override
	public ItemStack finishUsingItem(ItemStack stack, Level level, LivingEntity entity) {
		super.finishUsingItem(stack, level, entity);
		boolean single = stack.isEmpty();
		if (single) {
			stack.setCount(1);
		}

		PotionFlaskComponent flaskContents = stack.getOrDefault(TFDataComponents.POTION_FLASK_CONTENTS, PotionFlaskComponent.EMPTY);
		if (flaskContents.potion() == PotionContents.EMPTY)
			return stack;

		if (entity instanceof ServerPlayer player) {
			for (MobEffectInstance mobeffectinstance : flaskContents.potion().getAllEffects()) {
				if (mobeffectinstance.is(MobEffects.INSTANT_DAMAGE) != entity.isInvertedHealAndHarm() && mobeffectinstance.getAmplifier() > 0) {
					//custom harming death message for the advancement
					entity.hurtServer(player.level(), entity.damageSources().source(TFDamageTypes.FAILED_CHALLENGE), (float)(6 << mobeffectinstance.getAmplifier()));
				} else if (mobeffectinstance.getEffect().value().isInstantenous()) {
					mobeffectinstance.getEffect().value().applyInstantenousEffect(player.level(), player, player, player, mobeffectinstance.getAmplifier(), 1.0D);
				} else {
					player.addEffect(new MobEffectInstance(mobeffectinstance));
				}
			}
			if (!player.hasInfiniteMaterials() && !player.isSpectator()) {
				flaskContents.potion().potion().ifPresent(potion -> player.getData(TFDataAttachments.FLASK_DOSES).trackDrink(potion, player));
			}
		}

		if (entity.hasInfiniteMaterials())
			return stack;

		ItemStack drunk = single ? stack : stack.copyWithCount(1);
		PotionFlaskComponent remaining = flaskContents.removeDose();
		if (remaining.breakable()) {
			if (remaining.breakage() >= DOSES) {
				if (!level.isClientSide()) {
					level.playSound(null, entity, TFSounds.BRITTLE_FLASK_BREAK.get(), entity.getSoundSource(), 1.5F, 0.7F);
				}
				if (single) {
					stack.shrink(1);
				}
				return stack;
			}
			if (!level.isClientSide()) {
				level.playSound(null, entity, TFSounds.BRITTLE_FLASK_CRACK.get(), entity.getSoundSource(), 1.5F, 2.0F);
			}
		}

		drunk.set(TFDataComponents.POTION_FLASK_CONTENTS, remaining);
		if (!single && entity instanceof Player player) {
			InventoryUtil.giveItemToPlayer(player, drunk);
		}
		return stack;
	}

public void trigger(ServerPlayer player, int doses, int seconds, Holder<Potion> potion) {
		this.trigger(player, (instance) -> instance.matches(this, doses, seconds, potion));
	}

public boolean matches(DrinkFromFlaskTrigger parent, int doses, int seconds, Holder<Potion> potion) {
			return this.doses().matches(doses) && this.seconds().matches(seconds) && parent.holderMatcher.match(this.potion(), potion);
		}

private void resetFlaskLogic(AdvancementEvent.AdvancementEarnEvent event) {
		for (var criteria : event.getAdvancement().value().criteria().entrySet()) {
			if (criteria.getValue().trigger() instanceof DrinkFromFlaskTrigger) {
				event.getEntity().getData(TFDataAttachments.FLASK_DOSES).resetDoses();
				break;
			}
		}
	}

public void resetDoses() {
		this.dosesDrank = 0;
		this.lastUsedPotion = null;
	}

public static void travellersGearAutoRepair(LivingEntity livingEntity) {
		long lastHitTime = livingEntity.getData(TFDataAttachments.LAST_DAMAGE_ARMOR_TIME);
		if (livingEntity.level().getGameTime() - lastHitTime <= 10 * 20)  // 10 seconds
			return;

		for (EquipmentSlot slot : EquipmentSlotGroup.ARMOR.slots()) {
			ItemStack stack = livingEntity.getItemBySlot(slot);

			Float probability = stack.get(TFDataComponents.AUTO_REPAIR_PROBABILITY);
			if (probability == null || !TravellersModifiersManager.isModifierActive(livingEntity, stack, TravellersModifiersManager.AUTO_REPAIR_MODIFIER))
				continue;
			Level level = livingEntity.level();
			double boostedProbability = getAutoRepairChance(probability, level, livingEntity.blockPosition());

			if (boostedProbability > level.getRandom().nextFloat())
				stack.setDamageValue(Math.max(stack.getDamageValue() - 1, 0));

		}
	}

