private void updateOtherModifiers(EntityTickEvent.Post event) {
		if (!(event.getEntity() instanceof LivingEntity livingEntity)) return;
		TravellersGearLogic.travellersWingsGradualGlide(livingEntity);
		TravellersGearLogic.travellersBootsUnrestrained(livingEntity);
		TravellersGearLogic.travellersBootsSlimySolesBounce(livingEntity);

		if (livingEntity.level().isClientSide()) return;
		TravellersGearLogic.travellersVestHaste(livingEntity);
		TravellersGearLogic.travellersWingsHighJump(livingEntity);
		TravellersGearLogic.travellersGearAutoRepair(livingEntity);
		TravellersGearLogic.travellersBootsStraightAhead(livingEntity);
		TravellersGearLogic.determineWingState(livingEntity);
		TravellersGearLogic.travellersGogglesZoom(livingEntity);
	}

private void setLastDamageArmorTime(ArmorHurtEvent event) {
		if (Arrays.stream(EquipmentSlot.values()).noneMatch(slot -> event.getNewDamage(slot) > 0)) return;
		LivingEntity entity = event.getEntity();
		entity.setData(TFDataAttachments.LAST_DAMAGE_ARMOR_TIME, entity.level().getGameTime());
	}

private void stopDamagingTravellersGear(ArmorHurtEvent event) {
		if (event.isCanceled())
			return;

		event.getArmorMap().forEach((slot, _) -> {
			ItemStack damagedStack = event.getArmorItemStack(slot);
			if (!damagedStack.has(TFDataComponents.IS_TRAVELLERS_GEAR))
				return;

			int currentDamage = damagedStack.getDamageValue();
			float incomingDamage = event.getNewDamage(slot);
			int maxDamage = damagedStack.getMaxDamage();

			if (currentDamage < maxDamage - 1 && currentDamage + incomingDamage >= maxDamage - 1 && event.getEntity() instanceof ServerPlayer player) {
				player.connection.send(
					new ClientboundSoundPacket(SoundEvents.ITEM_BREAK, SoundSource.PLAYERS, player.getX(), player.getY(), player.getZ(), 1.0F, player.getVoicePitch(), player.getRandom().nextLong())
				);
			}

			if (currentDamage + incomingDamage >= maxDamage) {
				event.setNewDamage(slot, maxDamage - currentDamage - 1);
			}
		});
	}

private static double getAutoRepairChance(double baseProb, Level level, BlockPos pos) {
		if (!level.canSeeSky(pos))
			return baseProb;

		double boostFactor;  // 1 tick in boost ≈ boostFactor ticks without boost
		if (level.dimensionTypeRegistration().is(TFDimension.TWILIGHT_DIM_TYPE))
			boostFactor = AUTO_REPAIR_TWILIGHT_BOOST;
		else if (level.isBrightOutside())
			boostFactor = AUTO_REPAIR_SUNLIGHT_BOOST;
		else
			return baseProb;
		return TFMathUtil.probabilityOfAtLeastOneSuccess(baseProb, boostFactor);
	}

@Override
	public void onUpdate(ItemStack stack, World world, Entity entity, int slot, boolean isHeldInMainhand){
		boolean isHeld = isHeldInMainhand || entity instanceof EntityLivingBase && ItemStack.areItemStacksEqual(stack, ((EntityLivingBase) entity).getHeldItemOffhand());

		// If Wizardry.settings.wandsMustBeHeldToDecrementCooldown is false, the cooldowns will be decremented.
		// If Wizardry.settings.wandsMustBeHeldToDecrementCooldown is true and isHeld is true, the cooldowns will also be decremented.
		// If Wizardry.settings.wandsMustBeHeldToDecrementCooldown is true and isHeld is false, the cooldowns will not be decremented.
		if (!Wizardry.settings.wandsMustBeHeldToDecrementCooldown || isHeld) {
			WandHelper.decrementCooldowns(stack);
		}

		// Decrements wand damage (increases mana) every 1.5 seconds if it has a condenser upgrade
		if(!world.isRemote && !this.isManaFull(stack) && world.getTotalWorldTime() % Constants.CONDENSER_TICK_INTERVAL == 0){
			// If the upgrade level is 0, this does nothing anyway.
			int baseAmount = WandHelper.getUpgradeLevel(stack, WizardryItems.condenser_upgrade);
			int amount = (int)(baseAmount * Wizardry.settings.condenserAmountMultiplier);
			this.rechargeMana(stack, amount);
		}
	}

@Override
	public boolean canCast(ItemStack stack, Spell spell, EntityPlayer caster, EnumHand hand, int castingTick, SpellModifiers modifiers){

		// Spells can only be cast if the casting events aren't cancelled...
		if(castingTick == 0){
			if(MinecraftForge.EVENT_BUS.post(new SpellCastEvent.Pre(Source.WAND, spell, caster, modifiers))) return false;
		}else{
			if(MinecraftForge.EVENT_BUS.post(new SpellCastEvent.Tick(Source.WAND, spell, caster, modifiers, castingTick))) return false;
		}

		int cost = (int)(spell.getCost() * modifiers.get(SpellModifiers.COST) + 0.1f); // Weird floaty rounding

		// As of wizardry 4.2 mana cost is only divided over two intervals each second
		if(spell.isContinuous) cost = getDistributedCost(cost, castingTick);

		// ...and the wand has enough mana to cast the spell...
		return cost <= this.getMana(stack) // This comes first because it changes over time
				// ...and the wand is the same tier as the spell or higher...
				&& spell.getTier().level <= this.tier.level
				// ...and either the spell is not in cooldown or the player is in creative mode
				&& (WandHelper.getCurrentCooldown(stack) == 0 || caster.isCreative());
	}

@Override
	public boolean cast(ItemStack stack, Spell spell, EntityPlayer caster, EnumHand hand, int castingTick, SpellModifiers modifiers){

		World world = caster.world;

		if(world.isRemote && !spell.isContinuous && spell.requiresPacket()) return false;

		if(spell.cast(world, caster, hand, castingTick, modifiers)){

			if(castingTick == 0) MinecraftForge.EVENT_BUS.post(new SpellCastEvent.Post(Source.WAND, spell, caster, modifiers));

			if(!world.isRemote){

				// Continuous spells never require packets so don't rely on the requiresPacket method to specify it
				if(!spell.isContinuous && spell.requiresPacket()){
					// Sends a packet to all players in dimension to tell them to spawn particles.
					IMessage msg = new PacketCastSpell.Message(caster.getEntityId(), hand, spell, modifiers);
					WizardryPacketHandler.net.sendToDimension(msg, world.provider.getDimension());
				}

				// Mana cost
				int cost = (int)(spell.getCost() * modifiers.get(SpellModifiers.COST) + 0.1f); // Weird floaty rounding
				// As of wizardry 4.2 mana cost is only divided over two intervals each second
				if(spell.isContinuous) cost = getDistributedCost(cost, castingTick);

				if(cost > 0) this.consumeMana(stack, cost, caster);

			}

			caster.setActiveHand(hand);

			// Cooldown
			if(!spell.isContinuous && !caster.isCreative()){ // Spells only have a cooldown in survival
				WandHelper.setCurrentCooldown(stack, (int)(spell.getCooldown() * modifiers.get(WizardryItems.cooldown_upgrade)));
			}

			// Progression
			if(this.tier.level < Tier.MASTER.level && castingTick % CONTINUOUS_TRACKING_INTERVAL == 0){

				// We don't care about cost modifiers here, otherwise players would be penalised for wearing robes!
				int progression = (int)(spell.getCost() * modifiers.get(SpellModifiers.PROGRESSION));
				WandHelper.addProgression(stack, progression);

				if(!Wizardry.settings.legacyWandLevelling){ // Don't display the message if legacy wand levelling is enabled
					// If the wand just gained enough progression to be upgraded...
					Tier nextTier = tier.next();
					int excess = WandHelper.getProgression(stack) - nextTier.getProgression();
					if(excess >= 0 && excess < progression){
						// ...display a message above the player's hotbar
						caster.playSound(WizardrySounds.ITEM_WAND_LEVELUP, 1.25f, 1);
						WizardryAdvancementTriggers.wand_levelup.triggerFor(caster);
						if(!world.isRemote)
							caster.sendMessage(new TextComponentTranslation("item." + Wizardry.MODID + ":wand.levelup",
									this.getItemStackDisplayName(stack), nextTier.getNameForTranslationFormatted()));
					}
				}

				WizardData.get(caster).trackRecentSpell(spell);
			}

			return true;
		}

		return false;
	}

@Override
	public void onPlayerStoppedUsing(ItemStack stack, World world, EntityLivingBase user, int timeLeft){

		if(user instanceof EntityPlayer){

			EntityPlayer player = (EntityPlayer)user;

			Spell spell = WandHelper.getCurrentSpell(stack);

			SpellModifiers modifiers;

			if(WizardData.get(player) != null){
				modifiers = WizardData.get(player).itemCastingModifiers;
			}else{
				modifiers = this.calculateModifiers(stack, (EntityPlayer)user, spell); // Fallback to the old way, should never be used
			}

			int castingTick = stack.getMaxItemUseDuration() - timeLeft; // Might as well include this

			int cost = getDistributedCost((int)(spell.getCost() * modifiers.get(SpellModifiers.COST) + 0.1f), castingTick);

			// Still need to check there's enough mana or the spell will finish twice, since running out of mana is
			// handled separately.
			if(spell.isContinuous && spell.getTier().level <= this.tier.level && cost <= this.getMana(stack)){

				MinecraftForge.EVENT_BUS.post(new SpellCastEvent.Finish(Source.WAND, spell, player, modifiers, castingTick));
				spell.finishCasting(world, player, Double.NaN, Double.NaN, Double.NaN, null, castingTick, modifiers);

				if(!player.isCreative()){ // Spells only have a cooldown in survival
					WandHelper.setCurrentCooldown(stack, (int)(spell.getCooldown() * modifiers.get(WizardryItems.cooldown_upgrade)));
				}
			}
		}
	}

public static int[] getCooldowns(ItemStack wand){

		int[] cooldowns = new int[0];

		if(wand.getTagCompound() != null){

			return wand.getTagCompound().getIntArray(COOLDOWN_ARRAY_KEY);
		}

		return cooldowns;
	}

public static void setCooldowns(ItemStack wand, int[] cooldowns){

		if(wand.getTagCompound() == null) wand.setTagCompound((new NBTTagCompound()));

		wand.getTagCompound().setIntArray(COOLDOWN_ARRAY_KEY, cooldowns);
	}

public static void decrementCooldowns(ItemStack wand){

		int[] cooldowns = getCooldowns(wand);

		// If there are no cooldowns, it is assumed that they are all zero and therefore nothing needs to be done.
		if(cooldowns.length == 0) return;

		for(int i = 0; i < cooldowns.length; i++){
			if(cooldowns[i] > 0) cooldowns[i]--;
			if(cooldowns[i] < 0) cooldowns[i] = 0; // In case it got broken
		}

		setCooldowns(wand, cooldowns);
	}

public static int getCurrentCooldown(ItemStack wand){

		if(wand.getTagCompound() == null) wand.setTagCompound(new NBTTagCompound());

		int[] cooldowns = getCooldowns(wand);

		int selectedSpell = wand.getTagCompound().getInteger(SELECTED_SPELL_KEY);

		if(selectedSpell < 0 || cooldowns.length <= selectedSpell) return 0;
		// Don't need to check if the tag compound is null since the above check is equivalent.
		return cooldowns[selectedSpell];
	}

public static void setCurrentCooldown(ItemStack wand, int cooldown){

		if(wand.getTagCompound() == null) wand.setTagCompound((new NBTTagCompound()));

		int[] cooldowns = getCooldowns(wand);

		int selectedSpell = wand.getTagCompound().getInteger(SELECTED_SPELL_KEY);
		int spellCount = getSpells(wand).length;

		if(spellCount <= selectedSpell) return; // Probably shouldn't happen

		// The length of the spells array must be greater than 0 since this method can only be called if a spell is
		// cast, which is impossible if there are no spells.
		if(cooldowns.length <= selectedSpell) cooldowns = new int[spellCount];

		if(cooldown <= 0) cooldown = 1;

		cooldowns[selectedSpell] = cooldown;

		setCooldowns(wand, cooldowns);

		int[] maxCooldowns = getMaxCooldowns(wand);

		if(maxCooldowns.length <= selectedSpell) maxCooldowns = new int[spellCount];

		maxCooldowns[selectedSpell] = cooldown;

		setMaxCooldowns(wand, maxCooldowns);
	}

public static boolean selectSpell(ItemStack wand, int index){

		if(index < 0 || index > getSpells(wand).length) return false; // Out-of-bounds

		// 5 here because if the spell array doesn't exist, the wand can't possibly have attunement upgrades
		if(getSpells(wand).length < 0) setSpells(wand, new Spell[ItemWand.BASE_SPELL_SLOTS]);

		if(wand.getTagCompound() != null){
			wand.getTagCompound().setInteger(SELECTED_SPELL_KEY, index);
		}

		return true;
	}
